import React, { useState, useMemo } from "react";
import { FaInstagram, FaFacebookF, FaTwitter } from "react-icons/fa";
import { useCart } from "react-use-cart";
import { useNavigate } from "react-router-dom";

import {
  Gem,
  Sparkles,
  CircleDot,
  Star,
  Link2,
  Watch,
  ShoppingBag,
} from "lucide-react";

import Products from "./products/Products";

/* ============================================================
   FONTS
   ============================================================ */

const fontImport = `
  @import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,400;0,500;0,600;1,400&family=Jost:wght@300;400;500;600&display=swap');
`;

/* ============================================================
   CATEGORY DATA
   ============================================================ */

const CATEGORIES = [
  {
    id: "All",
    label: "All",
    icon: Sparkles,
  },
  {
    id: "Rings",
    label: "Rings",
    icon: Gem,
  },
  {
    id: "Necklaces",
    label: "Necklaces",
    icon: Sparkles,
  },
  {
    id: "Bracelets",
    label: "Bracelets",
    icon: CircleDot,
  },
  {
    id: "Earrings",
    label: "Earrings",
    icon: Star,
  },
  {
    id: "Chains",
    label: "Chains",
    icon: Link2,
  },
  {
    id: "Watches",
    label: "Watches",
    icon: Watch,
  },
];

/* ============================================================
   FOOTER
   ============================================================ */

function PlaceholderFooter() {
  return (
    <footer className="lux-footer">
      <div className="lux-footer-inner">

        {/* BRAND */}
        <div className="lux-footer-col lux-footer-brand">

          <div className="lux-logo lux-logo-footer">
            MAISON&nbsp;&amp;&nbsp;LUXE
          </div>

          <p>
            Fine accessories, crafted with intention.
            Timeless pieces for every story.
          </p>

          <div className="lux-footer-social">

            <a
              href="#"
              aria-label="Instagram"
              onClick={(e) => e.preventDefault()}
            >
              <FaInstagram size={16} />
            </a>

            <a
              href="#"
              aria-label="Facebook"
              onClick={(e) => e.preventDefault()}
            >
              <FaFacebookF size={16} />
            </a>

            <a
              href="#"
              aria-label="Twitter"
              onClick={(e) => e.preventDefault()}
            >
              <FaTwitter size={16} />
            </a>

          </div>

        </div>

        {/* SHOP */}
        <div className="lux-footer-col">

          <h4>Shop</h4>

          <a
            href="#"
            onClick={(e) => e.preventDefault()}
          >
            Rings
          </a>

          <a
            href="#"
            onClick={(e) => e.preventDefault()}
          >
            Necklaces
          </a>

          <a
            href="#"
            onClick={(e) => e.preventDefault()}
          >
            Watches
          </a>

        </div>

        {/* SUPPORT */}
        <div className="lux-footer-col">

          <h4>Support</h4>

          <a
            href="#"
            onClick={(e) => e.preventDefault()}
          >
            Shipping
          </a>

          <a
            href="#"
            onClick={(e) => e.preventDefault()}
          >
            Returns
          </a>

          <a
            href="#"
            onClick={(e) => e.preventDefault()}
          >
            Contact Us
          </a>

        </div>

        {/* NEWSLETTER */}
        <div className="lux-footer-col">

          <h4>Newsletter</h4>

          <p>
            Be first to know about new arrivals.
          </p>

          <div className="lux-footer-form">

            <input
              type="email"
              placeholder="Your email"
            />

            <button type="button">
              Join
            </button>

          </div>

        </div>

      </div>

      <div className="lux-footer-bottom">
        © {new Date().getFullYear()} Maison &amp; Luxe.
        All rights reserved.
      </div>

    </footer>
  );
}

/* ============================================================
   PRODUCT CARD
   ============================================================ */

function ProductCard({ product }) {
  const Icon = product.category === "Rings"
    ? Gem
    : product.category === "Necklaces"
    ? Sparkles
    : product.category === "Bracelets"
    ? CircleDot
    : product.category === "Earrings"
    ? Star
    : product.category === "Chains"
    ? Link2
    : Watch;

  const [imgFailed, setImgFailed] = useState(false);

  const { addItem } = useCart();

  const navigate = useNavigate();

  /* ----------------------------------------------------------
     IMAGE
  ---------------------------------------------------------- */

  const showImage =
    product.thumbnail &&
    !imgFailed;

  /* ----------------------------------------------------------
     ADD TO CART
  ---------------------------------------------------------- */

  const handleAddToCart = () => {
    addItem(product);
  };

  /* ----------------------------------------------------------
     VIEW DETAILS
  ---------------------------------------------------------- */

  const handleViewDetails = () => {
    navigate(`/SingleProduct/${product.id}`);
  };

  return (
    <article className="lux-card">

      {/* IMAGE */}
      <div className="lux-card-media">

        {showImage ? (

          <img
            src={product.thumbnail}
            alt={product.title}
            className="lux-card-img"
            loading="lazy"
            onError={() => setImgFailed(true)}
          />

        ) : (

          <div className="lux-card-media-icon">

            <Icon
              size={40}
              strokeWidth={1}
            />

          </div>

        )}

        {/* BADGE */}
        {product.badge && (
          <span className="lux-card-badge">
            {product.badge}
          </span>
        )}

        {/* QUICK ADD */}
        <button
          type="button"
          className="lux-card-quickadd"
          aria-label={`Add ${product.title} to cart`}
          onClick={handleAddToCart}
        >

          <ShoppingBag
            size={16}
            strokeWidth={1.5}
          />

        </button>

      </div>

      {/* CARD BODY */}
      <div className="lux-card-body">

        {/* CATEGORY */}
        <span className="lux-card-eyebrow">
          {product.category}
        </span>

        {/* TITLE */}
        <h3 className="lux-card-name">
          {product.title}
        </h3>

        {/* PRICE */}
        <div className="lux-card-price">
          ${Number(product.price).toFixed(2)}
        </div>

        {/* ACTIONS */}
        <div className="lux-card-actions">

          {/* VIEW DETAILS */}
          <button
            type="button"
            className="lux-btn lux-btn-outline"
            onClick={handleViewDetails}
          >
            View Details
          </button>

          {/* ADD TO CART */}
          <button
            type="button"
            className="lux-btn lux-btn-solid"
            onClick={handleAddToCart}
          >
            Add to Cart
          </button>

        </div>

      </div>

    </article>
  );
}

/* ============================================================
   MAIN PAGE
   ============================================================ */

export default function CollectionsPage() {

  const [activeCategory, setActiveCategory] =
    useState("All");

  /* ----------------------------------------------------------
     FILTER PRODUCTS
  ---------------------------------------------------------- */

  const filteredProducts = useMemo(() => {

    if (activeCategory === "All") {
      return products;
    }

    return products.filter(
      (product) =>
        product.category === activeCategory
    );

  }, [activeCategory]);

  return (

    <div className="lux-root">

      {/* ======================================================
          STYLES
      ====================================================== */}

      <style>{`

        ${fontImport}

        /* ====================================================
           ROOT
        ==================================================== */

        .lux-root {
          --bg: #1B1714;
          --bg-alt: #15110F;
          --surface: #211C18;
          --surface-hover: #2A241F;
          --border: rgba(201, 166, 107, 0.18);
          --border-strong: rgba(201, 166, 107, 0.35);
          --gold: #C9A66B;
          --gold-light: #E2C994;
          --gold-dim: #A88A5A;
          --ivory: #F5EFE6;
          --muted: #A9A09A;
          --wine: #4A2630;

          background: var(--bg);

          background-image:
            radial-gradient(
              ellipse 60% 40% at 15% 0%,
              rgba(201,166,107,0.06),
              transparent 60%
            ),
            radial-gradient(
              ellipse 50% 35% at 100% 20%,
              rgba(201,166,107,0.05),
              transparent 60%
            );

          color: var(--ivory);
          font-family: "Jost", sans-serif;
          min-height: 100vh;

          -webkit-font-smoothing: antialiased;
        }

        .lux-root *,
        .lux-root *::before,
        .lux-root *::after {
          box-sizing: border-box;
        }

        /* ====================================================
           NAVBAR
        ==================================================== */

        .lux-navbar {
          border-bottom: 1px solid var(--border);
          background: rgba(27,23,20,0.9);
          position: sticky;
          top: 0;
          z-index: 20;
          backdrop-filter: blur(6px);
        }

        .lux-navbar-inner {
          max-width: 1240px;
          margin: 0 auto;
          padding: 18px 24px;

          display: flex;
          align-items: center;
          justify-content: space-between;

          gap: 16px;
        }

        .lux-navbar-menu {
          display: none;
        }

        .lux-logo {
          font-family: "Cormorant Garamond", serif;
          font-size: 22px;
          letter-spacing: 0.14em;
          color: var(--gold-light);
          font-weight: 500;
          white-space: nowrap;
        }

        .lux-navbar-links {
          display: flex;
          gap: 34px;
        }

        .lux-navbar-links a {
          color: var(--muted);
          text-decoration: none;
          font-size: 13px;
          letter-spacing: 0.08em;
          text-transform: uppercase;
          padding-bottom: 4px;
          border-bottom: 1px solid transparent;

          transition:
            color .2s ease,
            border-color .2s ease;
        }

        .lux-navbar-links a:hover,
        .lux-navbar-links a.active {
          color: var(--gold-light);
          border-color: var(--gold);
        }

        .lux-navbar-actions {
          display: flex;
          gap: 6px;
        }

        .lux-icon-btn {
          background: transparent;
          border: none;
          color: var(--ivory);
          padding: 8px;
          border-radius: 999px;
          cursor: pointer;

          display: flex;
          align-items: center;
          justify-content: center;

          transition:
            background .2s ease,
            color .2s ease;
        }

        .lux-icon-btn:hover {
          background: var(--surface-hover);
          color: var(--gold-light);
        }

        /* ====================================================
           HERO
        ==================================================== */

        .lux-hero {
          max-width: 1240px;
          margin: 0 auto;
          padding: 72px 24px 40px;
          text-align: center;
        }

        .lux-hero-eyebrow {
          font-size: 12px;
          letter-spacing: 0.32em;
          text-transform: uppercase;
          color: var(--gold-dim);
          margin-bottom: 14px;
        }

        .lux-hero h1 {
          font-family: "Cormorant Garamond", serif;
          font-weight: 500;
          font-size: clamp(36px, 6vw, 58px);
          letter-spacing: 0.02em;
          margin: 0;
          color: var(--ivory);
        }

        .lux-hero-divider {
          display: flex;
          align-items: center;
          justify-content: center;
          gap: 14px;

          margin: 22px auto 0;

          width: 220px;
        }

        .lux-hero-divider .line {
          height: 1px;
          flex: 1;

          background:
            linear-gradient(
              90deg,
              transparent,
              var(--gold),
              transparent
            );
        }

        .lux-hero-divider .diamond {
          width: 7px;
          height: 7px;

          background: var(--gold);

          transform: rotate(45deg);

          flex-shrink: 0;
        }

        .lux-hero p {
          margin: 22px auto 0;

          max-width: 480px;

          color: var(--muted);

          font-weight: 300;

          font-size: 15px;

          line-height: 1.7;
        }

        /* ====================================================
           FILTERS
        ==================================================== */

        .lux-filters {
          max-width: 1240px;
          margin: 0 auto;

          padding: 0 24px 56px;

          display: flex;
          flex-wrap: wrap;

          justify-content: center;

          gap: 12px;
        }

        .lux-filter-btn {
          display: flex;
          align-items: center;

          gap: 8px;

          padding: 10px 20px;

          border-radius: 999px;

          border: 1px solid var(--border);

          background: var(--surface);

          color: var(--muted);

          font-family: "Jost", sans-serif;

          font-size: 13px;

          letter-spacing: 0.06em;

          text-transform: uppercase;

          cursor: pointer;

          transition: all .25s ease;
        }

        .lux-filter-btn:hover {
          border-color: var(--border-strong);

          color: var(--gold-light);

          background: var(--surface-hover);
        }

        .lux-filter-btn.is-active {
          background:
            linear-gradient(
              135deg,
              var(--gold),
              #A9865A
            );

          border-color: var(--gold);

          color: #211B17;

          font-weight: 500;
        }

        .lux-filter-btn.is-active svg {
          color: #211B17;
        }

        /* ====================================================
           PRODUCT GRID
        ==================================================== */

        .lux-grid-section {
          max-width: 1240px;
          margin: 0 auto;

          padding: 0 24px 100px;
        }

        .lux-grid-meta {
          display: flex;

          justify-content: space-between;

          align-items: baseline;

          margin-bottom: 24px;

          color: var(--muted);

          font-size: 13px;

          letter-spacing: 0.04em;
        }

        .lux-grid-meta strong {
          color: var(--gold-light);

          font-weight: 500;
        }

        .lux-grid {
          display: grid;

          grid-template-columns:
            repeat(4, 1fr);

          gap: 26px;
        }

        /* ====================================================
           PRODUCT CARD
        ==================================================== */

        .lux-card {
          background: var(--surface);

          border: 1px solid var(--border);

          border-radius: 4px;

          overflow: hidden;

          display: flex;

          flex-direction: column;

          transition:
            transform .3s ease,
            border-color .3s ease,
            box-shadow .3s ease;
        }

        .lux-card:hover {
          transform: translateY(-4px);

          border-color: var(--border-strong);

          box-shadow:
            0 18px 40px rgba(0,0,0,0.35);
        }

        .lux-card-media {
          position: relative;

          aspect-ratio: 1 / 1;

          background:
            radial-gradient(
              circle at 30% 20%,
              rgba(201,166,107,0.14),
              transparent 55%
            ),
            linear-gradient(
              160deg,
              var(--bg-alt),
              #1a1512
            );

          display: flex;

          align-items: center;

          justify-content: center;

          overflow: hidden;
        }

        .lux-card-img {
          width: 100%;
          height: 100%;

          object-fit: cover;

          object-position: center;

          display: block;

          transition:
            transform .5s ease;
        }

        .lux-card:hover .lux-card-img {
          transform: scale(1.06);
        }

        .lux-card-media-icon {
          color: var(--gold-dim);
        }

        .lux-card:hover .lux-card-media-icon {
          color: var(--gold-light);
        }

        .lux-card-badge {
          position: absolute;

          top: 12px;
          left: 12px;

          background: var(--wine);

          color: var(--gold-light);

          font-size: 10px;

          letter-spacing: 0.08em;

          text-transform: uppercase;

          padding: 4px 10px;

          border-radius: 999px;

          z-index: 1;
        }

        .lux-card-quickadd {
          position: absolute;

          top: 10px;
          right: 10px;

          background:
            rgba(27,23,20,0.7);

          border: 1px solid var(--border);

          color: var(--ivory);

          width: 32px;
          height: 32px;

          border-radius: 999px;

          display: flex;

          align-items: center;

          justify-content: center;

          cursor: pointer;

          opacity: 0;

          transform: translateY(-4px);

          transition:
            opacity .2s ease,
            transform .2s ease,
            background .2s ease;

          z-index: 1;
        }

        .lux-card:hover .lux-card-quickadd {
          opacity: 1;

          transform: translateY(0);
        }

        .lux-card-quickadd:hover {
          background: var(--gold);

          color: #211B17;
        }

        .lux-card-body {
          padding: 18px 18px 20px;

          display: flex;

          flex-direction: column;

          gap: 6px;
        }

        .lux-card-eyebrow {
          font-size: 10.5px;

          letter-spacing: 0.14em;

          text-transform: uppercase;

          color: var(--gold-dim);
        }

        .lux-card-name {
          font-family:
            "Cormorant Garamond",
            serif;

          font-size: 20px;

          font-weight: 500;

          margin: 0;

          color: var(--ivory);

          line-height: 1.3;
        }

        .lux-card-price {
          font-size: 15px;

          color: var(--gold-light);

          font-weight: 400;

          margin: 2px 0 12px;

          letter-spacing: 0.02em;
        }

        .lux-card-actions {
          display: flex;

          gap: 8px;
        }

        .lux-btn {
          flex: 1;

          padding: 10px 12px;

          font-size: 11.5px;

          letter-spacing: 0.06em;

          text-transform: uppercase;

          border-radius: 3px;

          cursor: pointer;

          transition: all .2s ease;

          font-family: "Jost", sans-serif;
        }

        .lux-btn-outline {
          background: transparent;

          border: 1px solid var(--border-strong);

          color: var(--ivory);
        }

        .lux-btn-outline:hover {
          border-color: var(--gold);

          color: var(--gold-light);
        }

        .lux-btn-solid {
          background: var(--gold);

          border: 1px solid var(--gold);

          color: #211B17;

          font-weight: 500;
        }

        .lux-btn-solid:hover {
          background: var(--gold-light);

          border-color: var(--gold-light);
        }

        .lux-empty {
          text-align: center;

          padding: 60px 20px;

          color: var(--muted);
        }

        /* ====================================================
           FOOTER
        ==================================================== */

        .lux-footer {
          border-top: 1px solid var(--border);

          background: var(--bg-alt);
        }

        .lux-footer-inner {
          max-width: 1240px;

          margin: 0 auto;

          padding: 56px 24px 32px;

          display: grid;

          grid-template-columns:
            1.6fr 1fr 1fr 1.3fr;

          gap: 32px;
        }

        .lux-footer-col h4 {
          font-size: 12px;

          letter-spacing: 0.12em;

          text-transform: uppercase;

          color: var(--gold-light);

          margin: 0 0 16px;

          font-weight: 500;
        }

        .lux-footer-col a {
          display: block;

          color: var(--muted);

          text-decoration: none;

          font-size: 13.5px;

          margin-bottom: 10px;

          transition:
            color .2s ease;
        }

        .lux-footer-col a:hover {
          color: var(--gold-light);
        }

        .lux-footer-col p {
          color: var(--muted);

          font-size: 13.5px;

          line-height: 1.7;
        }

        .lux-logo-footer {
          margin-bottom: 14px;
        }

        .lux-footer-social {
          display: flex;

          gap: 10px;

          margin-top: 16px;
        }

        .lux-footer-social a {
          width: 32px;

          height: 32px;

          border: 1px solid var(--border);

          border-radius: 999px;

          display: flex;

          align-items: center;

          justify-content: center;

          color: var(--ivory);
        }

        .lux-footer-social a:hover {
          border-color: var(--gold);

          color: var(--gold-light);
        }

        .lux-footer-form {
          display: flex;

          gap: 8px;

          margin-top: 10px;
        }

        .lux-footer-form input {
          flex: 1;

          background: var(--surface);

          border: 1px solid var(--border);

          border-radius: 3px;

          padding: 9px 12px;

          color: var(--ivory);

          font-size: 13px;

          font-family: "Jost", sans-serif;
        }

        .lux-footer-form input::placeholder {
          color: var(--muted);
        }

        .lux-footer-form button {
          background: var(--gold);

          border: none;

          border-radius: 3px;

          padding: 0 16px;

          color: #211B17;

          font-size: 12px;

          text-transform: uppercase;

          letter-spacing: 0.05em;

          cursor: pointer;

          font-weight: 500;
        }

        .lux-footer-bottom {
          text-align: center;

          padding: 18px;

          border-top: 1px solid var(--border);

          color: var(--muted);

          font-size: 12px;
        }

        /* ====================================================
           RESPONSIVE
        ==================================================== */

        @media (max-width: 1080px) {

          .lux-grid {
            grid-template-columns:
              repeat(3, 1fr);
          }

        }

        @media (max-width: 780px) {

          .lux-grid {
            grid-template-columns:
              repeat(2, 1fr);

            gap: 16px;
          }

          .lux-navbar-links {
            display: none;
          }

          .lux-navbar-menu {
            display: flex;
          }

          .lux-footer-inner {
            grid-template-columns:
              1fr 1fr;
          }

        }

        @media (max-width: 460px) {

          .lux-grid {
            grid-template-columns:
              1fr;
          }

          .lux-hero {
            padding:
              48px 20px 32px;
          }

          .lux-footer-inner {
            grid-template-columns:
              1fr;
          }

        }

      `}</style>

      {/* ======================================================
          HERO
      ====================================================== */}

      <section className="lux-hero">

        <div className="lux-hero-eyebrow">
          The Full Edit
        </div>

        <h1>
          Our Collections
        </h1>

        <div className="lux-hero-divider">

          <span className="line" />

          <span className="diamond" />

          <span className="line" />

        </div>

        <p>
          Discover pieces designed to last a lifetime —
          rings, necklaces, bracelets, earrings, chains
          and watches, each finished by hand.
        </p>

      </section>

      {/* ======================================================
          FILTERS
      ====================================================== */}

      <nav
        className="lux-filters"
        aria-label="Product categories"
      >

        {CATEGORIES.map(
          ({ id, label, icon: Icon }) => (

            <button
              key={id}
              type="button"
              className={`lux-filter-btn ${
                activeCategory === id
                  ? "is-active"
                  : ""
              }`}
              onClick={() =>
                setActiveCategory(id)
              }
            >

              <Icon
                size={14}
                strokeWidth={1.5}
              />

              {label}

            </button>

          )
        )}

      </nav>

      {/* ======================================================
          PRODUCTS
      ====================================================== */}

      <section className="lux-grid-section">

        <div className="lux-grid-meta">

          <span>

            Showing{" "}

            <strong>
              {filteredProducts.length}
            </strong>{" "}

            {filteredProducts.length === 1
              ? "piece"
              : "pieces"}

          </span>

          <span>

            {activeCategory === "All"
              ? "All Collections"
              : activeCategory}

          </span>

        </div>

        {filteredProducts.length > 0 ? (

          <div className="lux-grid">

            {filteredProducts.map(
              (product) => (

                <ProductCard
                  key={product.id}
                  product={product}
                />

              )
            )}

          </div>

        ) : (

          <div className="lux-empty">
            No pieces found in this collection yet.
          </div>

        )}

      </section>

      {/* ======================================================
          FOOTER
      ====================================================== */}

      <PlaceholderFooter />

    </div>
  );
}
